-- StilDoors Stil: точні фото пропущених декорів з офіційних карток.
begin;
on conflict (product_slug,option_group,label) do update set image_path=excluded.image_path,is_active=true;
on conflict (product_slug,selections) do update set image_path=excluded.image_path,sort_order=excluded.sort_order,is_active=true;
commit;
select count(*) as додано_точних_фото from public.product_variants where product_slug in ('stildoors-stil-florida-official','stildoors-stil-london-official','stildoors-stil-mexico-official','stildoors-stil-slovenia-official','stildoors-stil-tanzania-official') and is_active;
